import json
from decimal import Decimal
from pathlib import Path
data = json.loads(Path("artifacts/radar_r2_finco_gap_evidence.json").read_text())
if data["status"] != "PASS":
    raise SystemExit(f"R2_BLOCKED: live proof not PASS: {data}")
key = str(data["asset"]["canonicalKey"])
if not key.startswith("4663:0x"):
    raise SystemExit("R2_BLOCKED: selected asset is not a canonical Robinhood Chain key")
if data["reference"]["currency"] != "USD":
    raise SystemExit("R2_BLOCKED: non-USD reference reached FINCO GAP")
if data["referenceStateAuthority"] != "R4_NOT_YET_APPLIED":
    raise SystemExit("R2_BLOCKED: R2 falsely claimed reference-state authority")

# C1: coherence policy fields present
policy = data.get("coherencePolicy", {})
if policy.get("maxEvidenceSkewSeconds") is None:
    raise SystemExit("R2_BLOCKED: coherence policy missing")
if policy.get("actualMaxSkewSeconds") is None:
    raise SystemExit("R2_BLOCKED: actual skew not recorded")

# C2: settlement conversion evidence at artifact level
sett = data.get("settlementConversionEvidence", {})
if not sett.get("contractAddress"):
    raise SystemExit("R2_BLOCKED: settlement contract address missing")
if sett.get("usdPerAsset") is None:
    raise SystemExit("R2_BLOCKED: settlement usdPerAsset missing")
if sett.get("observedAt") is None:
    raise SystemExit("R2_BLOCKED: settlement observedAt missing")

# C6: git HEAD and producedAt
if not data.get("gitHead") or data["gitHead"] == "UNKNOWN":
    raise SystemExit("R2_BLOCKED: git HEAD not recorded")
if not data.get("producedAt"):
    raise SystemExit("R2_BLOCKED: producedAt missing")

observations = data["observations"]
if len(observations) != 4:
    raise SystemExit("R2_BLOCKED: expected four size/side observations")
expected = {("BUY", "100"), ("BUY", "1000"), ("SELL", "100"), ("SELL", "1000")}
actual = {(item["side"], item["requestedNotionalUsd"]) for item in observations}
if actual != expected:
    raise SystemExit(f"R2_BLOCKED: observation matrix mismatch {actual}")
for item in observations:
    if item["side"] == "BUY" and item["referenceSide"] != "ASK":
        raise SystemExit("R2_BLOCKED: BUY did not use ASK")
    if item["side"] == "SELL" and item["referenceSide"] != "BID":
        raise SystemExit("R2_BLOCKED: SELL did not use BID")
    if item["costScope"] != "ROUTE_AMOUNTS_ONLY_FEES_AND_GAS_NOT_ADDED":
        raise SystemExit("R2_BLOCKED: cost scope changed")
    if item["referenceStateAuthority"] != "R4_NOT_YET_APPLIED":
        raise SystemExit("R2_BLOCKED: observation claimed R4 authority")
    # C1: per-observation timestamps
    if not item.get("settlementObservedAt"):
        raise SystemExit("R2_BLOCKED: settlementObservedAt missing from observation")
    # C2: per-observation settlement evidence
    sett_ev = item.get("settlementEvidence", {})
    if not sett_ev.get("contractAddress"):
        raise SystemExit("R2_BLOCKED: observation missing settlementEvidence.contractAddress")
    if sett_ev.get("usdPerAsset") is None:
        raise SystemExit("R2_BLOCKED: observation missing settlementEvidence.usdPerAsset")
    # C3: neutral midpoint present
    if item.get("gapToMidBps") is None:
        raise SystemExit("R2_BLOCKED: gapToMidBps missing")
    values = [
        Decimal(item["executionPriceUsdPerToken"]),
        Decimal(item["referencePriceUsdPerToken"]),
        Decimal(item["gapBps"]),
        Decimal(item["gapToMidBps"]),
    ]
    if not all(v.is_finite() for v in values):
        raise SystemExit("R2_BLOCKED: non-finite numeric observation")
    if values[0] <= 0 or values[1] <= 0:
        raise SystemExit("R2_BLOCKED: non-positive execution/reference price")

# C3: midpoint analytics block
mid = data.get("midpointAnalytics", {})
if not mid.get("refMidUsdPerToken"):
    raise SystemExit("R2_BLOCKED: midpointAnalytics missing")

# C4: size comparison block
sc = data.get("sizeComparison", {})
if sc.get("buyDirectionalGapDeltaBps") is None:
    raise SystemExit("R2_BLOCKED: sizeComparison buyDirectionalGapDeltaBps missing")
if sc.get("sellDirectionalGapDeltaBps") is None:
    raise SystemExit("R2_BLOCKED: sizeComparison sellDirectionalGapDeltaBps missing")

# D1 (sign): side-specific interpretation must be present
buy_interp = sc.get("buyDeltaInterpretation") or ""
sell_interp = sc.get("sellDeltaInterpretation") or ""
if not buy_interp.startswith("positive = larger size is worse"):
    raise SystemExit("R2_BLOCKED: BUY delta interpretation is not side-specific")
if not sell_interp.startswith("positive = larger size is better"):
    raise SystemExit("R2_BLOCKED: SELL delta interpretation is not side-specific")
if buy_interp == sell_interp:
    raise SystemExit("R2_BLOCKED: BUY and SELL delta interpretations must differ")
if "worse for that execution side" in (sc.get("semantics") or ""):
    raise SystemExit("R2_BLOCKED: generic 'positive = worse' claim reappeared")

# D1 (skew): coherence policy skew must not exceed declared maximum
actual_skew_str = policy.get("actualMaxSkewSeconds")
max_skew_str = policy.get("maxEvidenceSkewSeconds")
if actual_skew_str is None:
    raise SystemExit("R2_BLOCKED: actualMaxSkewSeconds missing")
if max_skew_str is None:
    raise SystemExit("R2_BLOCKED: maxEvidenceSkewSeconds missing")
if Decimal(str(actual_skew_str)) > Decimal(str(max_skew_str)):
    raise SystemExit(
        f"R2_BLOCKED: actualMaxSkewSeconds {actual_skew_str} exceeds "
        f"maxEvidenceSkewSeconds {max_skew_str}"
    )

# D2-final: R0 size-impact values must be present and parse as finite Decimal.
# Neither individually is required to be non-zero.
for field in ("r0BuySizeImpactBps", "r0SellSizeImpactBps"):
    val = sc.get(field)
    if val is None:
        raise SystemExit(f"R2_BLOCKED: sizeComparison {field} missing")
    try:
        parsed = Decimal(str(val))
    except Exception as e:
        raise SystemExit(f"R2_BLOCKED: sizeComparison {field} cannot parse as Decimal: {e}")
    if not parsed.is_finite():
        raise SystemExit(f"R2_BLOCKED: sizeComparison {field} is not finite")
if not sc.get("r0SizeImpactAuthority"):
    raise SystemExit("R2_BLOCKED: R0 size-impact authority statement missing")

# D3: PASS artifact must preserve the candidate audit trail
audit = data.get("candidateAttempts")
if not isinstance(audit, dict):
    raise SystemExit("R2_BLOCKED: candidateAttempts audit block missing from PASS")
if not isinstance(audit.get("skippedCandidates"), list):
    raise SystemExit("R2_BLOCKED: candidateAttempts.skippedCandidates must be a list")
if audit.get("skippedCandidateCount") != len(audit["skippedCandidates"]):
    raise SystemExit("R2_BLOCKED: candidateAttempts count does not match list length")
if audit.get("selectedSymbol") != data["asset"]["symbol"]:
    raise SystemExit("R2_BLOCKED: candidateAttempts selectedSymbol disagrees with asset")
# Acceptance is unchanged: observations are never stitched across candidates.
if len(observations) != 4:
    raise SystemExit("R2_BLOCKED: selected candidate must supply all four observations")

# C7: multiplier semantics
ref_block = data.get("reference", {})
if not ref_block.get("multiplierFormula"):
    raise SystemExit("R2_BLOCKED: multiplierFormula missing from reference block")
if not ref_block.get("rawBidUsdPerShare"):
    raise SystemExit("R2_BLOCKED: rawBidUsdPerShare missing")

print(
    f"R2_FINCO_GAP_PASS key={key} observations={len(observations)} "
    f"skew={policy['actualMaxSkewSeconds']}s policy={policy['maxEvidenceSkewSeconds']}s "
    f"selected={audit['selectedSymbol']} skippedCandidates={audit['skippedCandidateCount']}"
)
